## 消费者

```csharp
public class OrderCreatedConsumer : IConsumer<OrderSubmitted>
{
    private readonly ILogger<OrderCreatedConsumer> _logger;
    private readonly IEmailService _emailService;

    public OrderCreatedConsumer(
        ILogger<OrderCreatedConsumer> logger,
        IEmailService emailService)
    {
        _logger = logger;
        _emailService = emailService;
    }

    public async Task Consume(ConsumeContext<OrderSubmitted> context)
    {
        var message = context.Message;
        _logger.LogInformation($"处理订单 {message.OrderId}");

        // 发送确认邮件
        await _emailService.SendOrderConfirmationAsync(
            message.CustomerId,
            message.OrderId);
    }
}
```


## 发布消息

```csharp
public class OrderService
{
    private readonly IPublishEndpoint _publishEndpoint;
    private readonly ISendEndpointProvider _sendEndpointProvider;

    public OrderService(
        IPublishEndpoint publishEndpoint,
        ISendEndpointProvider sendEndpointProvider)
    {
        _publishEndpoint = publishEndpoint;
        _sendEndpointProvider = sendEndpointProvider;
    }

    // 发布事件
    public async Task SubmitOrderAsync(Order order)
    {
        // 处理订单
        await _publishEndpoint.Publish(new OrderSubmitted
        {
            OrderId = order.Id,
            CustomerId = order.CustomerId,
            TotalAmount = order.TotalAmount,
            SubmittedAt = DateTime.UtcNow
        });
    }

    // 发送命令
    public async Task ProcessOrderAsync(Guid orderId)
    {
        var endpoint = await _sendEndpointProvider.GetSendEndpoint(
            new Uri("queue:process-order"));

        await endpoint.Send(new ProcessOrder { OrderId = orderId });
    }
}
```

## 事件驱动架构

**事件溯源**：
```csharp
public class OrderAggregate
{
    private readonly List<IEvent> _events = new();

    public Guid Id { get; private set; }
    public OrderStatus Status { get; private set; }
    public decimal TotalAmount { get; private set; }

    public void Submit()
    {
        if (Status != OrderStatus.Draft)
            throw new InvalidOperationException("Order is not in draft status");

        var @event = new OrderSubmitted(Id, TotalAmount);
        Apply(@event);
        _events.Add(@event);
    }

    private void Apply(OrderSubmitted @event)
    {
        Status = OrderStatus.Submitted;
    }
}
```


## Saga 模式

```csharp
public class OrderStateMachine : MassTransitStateMachine<OrderState>
{
    public OrderStateMachine()
    {
        InstanceState(x => x.CurrentState);

        Event(() => OrderSubmitted, x => x.CorrelateById(m => m.Message.OrderId));
        Event(() => PaymentProcessed, x => x.CorrelateById(m => m.Message.OrderId));
        Event(() => OrderShipped, x => x.CorrelateById(m => m.Message.OrderId));

        Initially(
            When(OrderSubmitted)
                .Then(context =>
                {
                    context.Saga.OrderId = context.Message.OrderId;
                    context.Saga.CustomerId = context.Message.CustomerId;
                })
                .TransitionTo(Submitted)
                .Publish(context => new ProcessPayment
                {
                    OrderId = context.Message.OrderId,
                    Amount = context.Message.TotalAmount
                })
        );

        During(Submitted,
            When(PaymentProcessed)
                .TransitionTo(Paid)
                .Publish(context => new ShipOrder
                {
                    OrderId = context.Saga.OrderId
                })
        );

        During(Paid,
            When(OrderShipped)
                .TransitionTo(Shipped)
                .Publish(context => new OrderCompleted
                {
                    OrderId = context.Saga.OrderId
                })
        );
    }

    public Event<OrderSubmitted> OrderSubmitted { get; }
    public Event<PaymentProcessed> PaymentProcessed { get; }
    public Event<OrderShipped> OrderShipped { get; }

    public State Submitted { get; }
    public State Paid { get; }
    public State Shipped { get; }
}

public class OrderState : SagaStateMachineInstance
{
    public Guid CorrelationId { get; set; }
    public string CurrentState { get; set; }
    public Guid OrderId { get; set; }
    public string CustomerId { get; set; }
}
```


