using System;
using System.Collections.Generic;
using System.Threading.Tasks;
using MassTransit;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;

namespace MessageQueueDemo
{
    // 消息定义
    public record SubmitOrder
    {
        public Guid OrderId { get; init; }
        public string CustomerId { get; init; }
        public List<OrderItem> Items { get; init; }
        public decimal TotalAmount { get; init; }
    }

    public record OrderSubmitted
    {
        public Guid OrderId { get; init; }
        public string CustomerId { get; init; }
        public decimal TotalAmount { get; init; }
        public DateTime SubmittedAt { get; init; }
    }

    public record OrderItem
    {
        public string ProductId { get; init; }
        public int Quantity { get; init; }
        public decimal Price { get; init; }
    }

    public record ProcessPayment
    {
        public Guid OrderId { get; init; }
        public decimal Amount { get; init; }
    }

    public record PaymentProcessed
    {
        public Guid OrderId { get; init; }
        public bool Success { get; init; }
        public string TransactionId { get; init; }
    }

    // 消费者
    public class OrderSubmittedConsumer : IConsumer<OrderSubmitted>
    {
        private readonly ILogger<OrderSubmittedConsumer> _logger;
        private readonly IPublishEndpoint _publishEndpoint;

        public OrderSubmittedConsumer(
            ILogger<OrderSubmittedConsumer> logger,
            IPublishEndpoint publishEndpoint)
        {
            _logger = logger;
            _publishEndpoint = publishEndpoint;
        }

        public async Task Consume(ConsumeContext<OrderSubmitted> context)
        {
            var message = context.Message;
            _logger.LogInformation($"处理订单 {message.OrderId}，金额: {message.TotalAmount}");

            // 模拟处理
            await Task.Delay(1000);

            // 发布支付命令
            await _publishEndpoint.Publish(new ProcessPayment
            {
                OrderId = message.OrderId,
                Amount = message.TotalAmount
            });

            _logger.LogInformation($"订单 {message.OrderId} 处理完成，已发送支付命令");
        }
    }

    public class PaymentProcessedConsumer : IConsumer<PaymentProcessed>
    {
        private readonly ILogger<PaymentProcessedConsumer> _logger;

        public PaymentProcessedConsumer(ILogger<PaymentProcessedConsumer> logger)
        {
            _logger = logger;
        }

        public Task Consume(ConsumeContext<PaymentProcessed> context)
        {
            var message = context.Message;
            if (message.Success)
            {
                _logger.LogInformation($"订单 {message.OrderId} 支付成功，交易ID: {message.TransactionId}");
            }
            else
            {
                _logger.LogWarning($"订单 {message.OrderId} 支付失败");
            }

            return Task.CompletedTask;
        }
    }

    // 服务
    public class OrderService
    {
        private readonly IPublishEndpoint _publishEndpoint;
        private readonly ILogger<OrderService> _logger;

        public OrderService(IPublishEndpoint publishEndpoint, ILogger<OrderService> logger)
        {
            _publishEndpoint = publishEndpoint;
            _logger = logger;
        }

        public async Task SubmitOrderAsync(string customerId, List<OrderItem> items)
        {
            var orderId = Guid.NewGuid();
            var totalAmount = items.Sum(i => i.Price * i.Quantity);

            _logger.LogInformation($"提交订单 {orderId}");

            await _publishEndpoint.Publish(new OrderSubmitted
            {
                OrderId = orderId,
                CustomerId = customerId,
                TotalAmount = totalAmount,
                SubmittedAt = DateTime.UtcNow
            });
        }
    }

    // 消息状态机
    public class OrderStateMachine : MassTransitStateMachine<OrderState>\    {
        public OrderStateMachine()
        {
            InstanceState(x => x.CurrentState);

            Event(() => OrderSubmitted, x => x.CorrelateById(m => m.Message.OrderId));
            Event(() => PaymentProcessed, x => x.CorrelateById(m => m.Message.OrderId));

            Initially(
                When(OrderSubmitted)
                    .Then(context =>
                    {
                        context.Saga.OrderId = context.Message.OrderId;
                        context.Saga.CustomerId = context.Message.CustomerId;
                        context.Saga.TotalAmount = context.Message.TotalAmount;
                    })
                    .TransitionTo(Submitted)
                    .Publish(context => new ProcessPayment
                    {
                        OrderId = context.Message.OrderId,
                        Amount = context.Message.TotalAmount
                    })
            );

            During(Submitted,
                When(PaymentProcessed)
                    .Then(context =>
                    {
                        context.Saga.TransactionId = context.Message.TransactionId;
                    })
                    .TransitionTo(Paid)
            );
        }

        public Event<OrderSubmitted> OrderSubmitted { get; }
        public Event<PaymentProcessed> PaymentProcessed { get; }

        public State Submitted { get; }
        public State Paid { get; }
    }

    public class OrderState : SagaStateMachineInstance
    {
        public Guid CorrelationId { get; set; }
        public string CurrentState { get; set; }
        public Guid OrderId { get; set; }
        public string CustomerId { get; set; }
        public decimal TotalAmount { get; set; }
        public string TransactionId { get; set; }
    }

    // 配置服务
    public static class MessageQueueServiceCollectionExtensions
    {
        public static IServiceCollection AddMessageQueueServices(this IServiceCollection services)
        {
            services.AddMassTransit(x =>
            {
                x.AddConsumer<OrderSubmittedConsumer>();
                x.AddConsumer<PaymentProcessedConsumer>();
                x.AddSagaStateMachine<OrderStateMachine, OrderState>()
                    .InMemoryRepository();

                x.UsingRabbitMq((context, cfg) =>
                {
                    cfg.Host("localhost", "/", h =>
                    {
                        h.Username("guest");
                        h.Password("guest");
                    });

                    cfg.ReceiveEndpoint("order-submitted", e =>
                    {
                        e.UseMessageRetry(r => r.Interval(3, TimeSpan.FromSeconds(5)));
                        e.ConfigureConsumer<OrderSubmittedConsumer>(context);
                    });

                    cfg.ReceiveEndpoint("payment-processed", e =>
                    {
                        e.ConfigureConsumer<PaymentProcessedConsumer>(context);
                    });

                    cfg.ReceiveEndpoint("order-state", e =>
                    {
                        e.ConfigureSaga<OrderState>(context);
                    });
                });
            });

            services.AddMassTransitHostedService();

            services.AddScoped<OrderService>();

            return services;
        }
    }
}
